import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const projectRoot = process.cwd();
const sourceRoot = path.join(projectRoot, "src");
const outputFile = path.join(sourceRoot, "components/icon/bundled-icons.generated.ts");
const iconNamePattern = /["'`]([a-z][a-z0-9-]*):([a-z0-9][a-z0-9-]*)["'`]/gi;

async function listSourceFiles(directory) {
	const entries = await readdir(directory, { withFileTypes: true });
	const files = await Promise.all(
		entries.map(async (entry) => {
			const entryPath = path.join(directory, entry.name);
			if (entry.isDirectory()) return listSourceFiles(entryPath);
			if (/\.(?:ts|tsx)$/.test(entry.name) && entryPath !== outputFile) return [entryPath];
			return [];
		}),
	);
	return files.flat();
}

async function fetchJson(url) {
	const response = await fetch(url);
	if (!response.ok) throw new Error(`${response.status} ${response.statusText}: ${url}`);
	return response.json();
}

const collections = await fetchJson("https://api.iconify.design/collections");
const validPrefixes = new Set(Object.keys(collections));
const iconsByPrefix = new Map();

for (const file of await listSourceFiles(sourceRoot)) {
	const source = await readFile(file, "utf8");
	for (const match of source.matchAll(iconNamePattern)) {
		const [, prefix, iconName] = match;
		if (prefix === "local" || !validPrefixes.has(prefix)) continue;
		const names = iconsByPrefix.get(prefix) ?? new Set();
		names.add(iconName);
		iconsByPrefix.set(prefix, names);
	}
}

const bundledCollections = [];
for (const [prefix, names] of [...iconsByPrefix].sort(([a], [b]) => a.localeCompare(b))) {
	const icons = [...names].sort();
	const query = new URLSearchParams({ icons: icons.join(",") });
	const collection = await fetchJson(`https://api.iconify.design/${prefix}.json?${query}`);
	if (collection.not_found?.length) {
		throw new Error(`Unknown ${prefix} icons: ${collection.not_found.join(", ")}`);
	}
	delete collection.not_found;
	bundledCollections.push(collection);
}

const banner = `/* eslint-disable */\n// Generated by scripts/generate-iconify-bundle.mjs. Do not edit manually.\n`;
const moduleSource = `${banner}export const bundledIconCollections = ${JSON.stringify(bundledCollections)};\n`;
await writeFile(outputFile, moduleSource, "utf8");

const iconCount = [...iconsByPrefix.values()].reduce((total, names) => total + names.size, 0);
console.log(`Bundled ${iconCount} Iconify icons from ${iconsByPrefix.size} collections.`);
